-- KB-027 API-key scope, expiration, rotation and revocation semantics.
-- Additive: do not mutate previous migrations, customer assessments, findings, evidence or deployment decisions.
UPDATE risk_knowledge_entries SET problem_json='{"statement":"One leaked key can operate every project, environment or high-impact tool indefinitely.","customer_symptom":"A key intended for one project, environment or limited tool can unexpectedly access another project, production-like environment or privileged operation, including after expiry, rotation or revocation.","credible_failure_or_attack":"A leaked, shared or stale API key is accepted outside its authorized project, environment, operation or validity window because a gateway or downstream verifier omits scope, lifetime or revocation enforcement.","affected_assets":["agent and MCP tool gateways","API issuers, credentials and verifier state","provider projects and environments","privileged tool actions and downstream records","credential rotation, expiration and revocation controls","redacted authorization and audit events"],"default_severity":"high","severity_rationale":"Over-scoped or long-lived API keys can amplify credential compromise. Final severity depends on reachable projects, environments, tools, data, lifetime and revocation controls.","applicability":["API-integrated agents"],"threat_actor_or_failure_source":"credential theft or accidental sharing, excessive issuance scope, missing verifier checks, stale revocation caches or rotation failure","trust_boundary":"Every receiving API/tool must independently bind a credential to issuer, project, environment, audience, permitted action and effective validity/revocation state before data access or side effects.","operational_impact":"Excessive or stale key authority may disclose project data or trigger unauthorized, costly or high-impact tools. Containment may require immediate revocation, route isolation, event review and exact-version retest."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-027 API-key scope, lifetime, project, environment or permitted-action change","ARL-KB-027 key issuance, storage, rotation or revocation mechanism change","ARL-KB-027 key leakage, cross-project use, excessive-scope use or revocation failure","ARL-KB-027 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"candidate semantic correction; independent practitioner and customer validation required"}', content_digest='56f0bf217306b3792d19af4c30d2d71d6d74645583cf7fbfe0d4a91a9585ffb2', updated_at='2026-10-11' WHERE id='ARL-KB-027';
UPDATE risk_knowledge_checks SET objective='Determine whether applicable agent API keys are constrained to attributable owner, approved project, environment, intended actions, expiration and revocation at the receiving service before disclosure or side effects.', method='Bind the review to the exact frozen build and applicable APIs/tools. Inspect the organisation-approved secret-free key inventory and receiving-side project/environment, scope, audience, expiration, revocation, rotation and storage controls. Under separate written owner-authorised ROE, test bounded synthetic in-scope requests and negative cross-project, cross-environment, elevated-action, expired, revoked and superseded-key requests; correlate authorization decisions and actual downstream state. Do not collect raw secrets or treat file references or error codes as proof of enforcement.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-027 exact assessed system, version, environment, API/tool routes, issuer and permitted project, operation and data scope","ARL-KB-027 organisation-approved secret-free key owner, project/environment, audience, scope, expiration, rotation, revocation and exception inventory","ARL-KB-027 source or configuration evidence for key issuance, scope and expiry enforcement, storage redaction, rotation, revocation and fail-closed receiving API checks","ARL-KB-027 bounded positive evidence of owner-authorised synthetic scoped keys completing permitted project, environment and tool actions with attributable results","ARL-KB-027 bounded negative evidence of wrong-project, wrong-environment, privileged, expired, revoked and superseded keys denied before data disclosure or downstream effects","ARL-KB-027 observed runtime credential reference, scope, expiry/revocation policy, API/tool authorization, correlated responses, audit events and downstream state","ARL-KB-027 tester and reviewer identity, written authorisation, roles, timestamps, assessed build, evidence digest, untested paths and accountable human decision"]', pass_condition='KB-027 passes only after accountable human review of exact-version key inventory and enforcement, successful synthetic authorised calls, denied cross-project, cross-environment, elevated, expired, revoked and superseded-key variants before disclosure/effects, and correlated downstream audit records with known limits.', fail_condition='KB-027 is a confirmed FAIL only when reproducible exact-build evidence demonstrates a wrongly scoped, expired, revoked or superseded API key performing an unauthorized operation, disclosing data or bypassing a receiving-side policy. Missing inventory, runtime proof, negative tests, authorization or reviewer signoff requires INCONCLUSIVE / EVIDENCE GAP / REVIEW REQUIRED: block PASS and deployment without inventing a confirmed vulnerability.', limitations='A bounded KB-027 review cannot prove absence of unknown keys, untested API routes, later deployment drift, provider-side unknown policies or future revocation delays. Static hints do not prove runtime key enforcement.', content_digest='6c6c0429cf87cb4aa85412fe8f2a4924e7813e7ba0cb7897f20a28b73b652155', updated_at='2026-10-11' WHERE entry_id='ARL-KB-027';
UPDATE risk_knowledge_solutions SET control_objective='Issue and enforce accountable minimum-scope API keys by project, environment, permitted operation and short validity, with effective receiver-side revocation and rotation before tool side effects.', recommended_remediation='Use project- and purpose-scoped short-lived keys with least privilege; display secrets only at issue time, store verifiers securely, rotate/revoke promptly and check audience, expiry, scope and revocation at each API or MCP tool boundary.', default_owner='Platform owner', priority='P0', implementation_principles_json='["ARL-KB-027: Bind keys to accountable owner, project, environment, audience and permitted action.","ARL-KB-027: Enforce short lifetime, effective revocation and superseded-key denial at each receiving API before any effects.","ARL-KB-027: Redact all raw key values from logs/evidence and protect key material or verifiers.","ARL-KB-027: Correlate gateway decisions to downstream results and audit revocation propagation."]', monitoring='Record redacted key reference, allowed project/environment, scope, issuance/expiry/revocation state, policy digest, decision, denial reason and downstream effects; alert on stale verifier acceptance or cross-scope use.', containment='Revoke affected keys and dependent credentials, disable impacted API or tool paths, halt queued high-impact actions, preserve redacted traces and require accountable re-enablement.', retest_acceptance_json='["ARL-KB-027: Approved exact-build key inventory and lifetime, project, environment, action and revocation policies are versioned.","ARL-KB-027: Permitted synthetic scoped key calls succeed with expected downstream results.","ARL-KB-027: Cross-project, cross-environment, privileged, expired, revoked and superseded synthetic keys are denied before disclosure or material action.","ARL-KB-027: Reviewer records written ROE, exact build, evidence digests, untested paths, residual limitations and retest decision."]', content_digest='34b62cb9707295d42846311df185a537b3190e562e5c0091419b8a451612da79', updated_at='2026-10-11' WHERE entry_id='ARL-KB-027';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='e4c586d45e144215dc20daf19c78ea95810b4f17bd3fb20b5950aac5e5c4f10b', updated_at='2026-10-11' WHERE entry_id='ARL-KB-027';
